"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useId, useState } from "react";

import { cn } from "@/lib/utils";

/** One requirement shown under the field. `test` returns true once the password meets it. */
export type PasswordRule = { label: string; test: (password: string) => boolean };

/**
 * Props for a password field with a strength meter. Pass `value` to control it, or `defaultValue` to let it hold
 * its own state. Every other input attribute, such as `name` or `required`, lands on the input; `className`
 * lands on the wrapper.
 */
export type PasswordStrengthProps = Omit<
  ComponentPropsWithoutRef<"input">,
  "value" | "defaultValue" | "onChange" | "type" | "children"
> & {
  value?: string;
  defaultValue?: string;
  /** Receives the new password and its score from 0 to 4, the number of filled segments. */
  onValueChange?: (value: string, score: number) => void;
  /** The visible label of the field. */
  label?: ReactNode;
  /** The rules listed under the meter. Replace them to translate them or to change the policy. */
  rules?: PasswordRule[];
  /** The five strength words, from a score of 0 to a score of 4. */
  strengthLabels?: [string, string, string, string, string];
};

const DEFAULT_RULES: PasswordRule[] = [
  { label: "At least 8 characters", test: (password) => password.length >= 8 },
  { label: "A number", test: (password) => /\d/.test(password) },
  { label: "A symbol", test: (password) => /[^\p{L}\p{N}\s]/u.test(password) },
];
const DEFAULT_LABELS: PasswordStrengthProps["strengthLabels"] = ["Very weak", "Weak", "Fair", "Good", "Strong"];
// The rules fill three segments. The fourth fills when every rule is met and the password is this long.
const STRONG_LENGTH = 12;
const SEGMENTS = 4;

// The system reports a result, so each segment eases out and lands once.
const FILL: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };
// Each segment starts this long after its neighbour, so the meter fills one by one.
const STAGGER = 0.05;

function scoreOf(password: string, rules: PasswordRule[]) {
  if (!password || rules.length === 0) return 0;
  const met = rules.filter((rule) => rule.test(password)).length;
  const fromRules = Math.round((met / rules.length) * (SEGMENTS - 1));
  return fromRules + (met === rules.length && password.length >= STRONG_LENGTH ? 1 : 0);
}

function EyeGlyph({ crossed }: { crossed: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <path
        fillRule="evenodd"
        d="M8 3C4.4 3 1.7 5.6 1 8c.7 2.4 3.4 5 7 5s6.3-2.6 7-5c-.7-2.4-3.4-5-7-5Zm0 7.5a2.5 2.5 0 1 1 0-5 2.5 2.5 0 0 1 0 5Z"
      />
      {crossed && <path d="m2.5 2.5 11 11" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" />}
    </svg>
  );
}

function RuleMark({ met, transition }: { met: boolean; transition: Transition }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "flex size-4 shrink-0 items-center justify-center rounded-full border",
        met ? "border-primary bg-primary text-primary-foreground" : "border-muted-foreground/60",
      )}
    >
      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" className="size-3">
        <motion.path
          d="m3.5 8.5 3 3 6-6.5"
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={false}
          animate={{ pathLength: met ? 1 : 0, opacity: met ? 1 : 0 }}
          transition={transition}
        />
      </svg>
    </span>
  );
}

/**
 * A password field that shows how strong the password is while the person types. Four segments fill one by one,
 * a word names the strength, and each rule ticks as the password meets it. The score is a guide for the
 * person, not a security check: validate the password on the server as well.
 */
export function PasswordStrength({
  value,
  defaultValue = "",
  onValueChange,
  label = "Password",
  rules = DEFAULT_RULES,
  strengthLabels = DEFAULT_LABELS,
  className,
  id,
  disabled,
  ...inputProps
}: PasswordStrengthProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const [visible, setVisible] = useState(false);
  const ownId = useId();
  const inputId = id ?? `${ownId}-input`;
  const rulesId = `${ownId}-rules`;
  const reduceMotion = useReducedMotion();
  const password = value ?? ownValue;
  const score = scoreOf(password, rules);
  const word = password ? strengthLabels?.[score] : undefined;

  return (
    <div className={cn("flex w-full flex-col gap-2 text-sm", className)}>
      <label htmlFor={inputId} className="font-medium text-foreground">
        {label}
      </label>
      <div className="relative">
        <input
          autoComplete="new-password"
          spellCheck={false}
          {...inputProps}
          id={inputId}
          type={visible ? "text" : "password"}
          value={password}
          disabled={disabled}
          aria-describedby={cn(rulesId, inputProps["aria-describedby"])}
          onChange={(event) => {
            const next = event.target.value;
            if (value === undefined) setOwnValue(next);
            onValueChange?.(next, scoreOf(next, rules));
          }}
          // 16px text on a phone stops iOS from zooming into the field.
          className="h-11 w-full rounded-lg border border-border bg-background pl-3 pr-12 text-base text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 sm:text-sm"
        />
        <button
          type="button"
          aria-label="Show password"
          aria-pressed={visible}
          disabled={disabled}
          onClick={() => setVisible(!visible)}
          className="absolute inset-y-0 right-0 flex w-11 cursor-pointer items-center justify-center rounded-lg text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed"
        >
          <EyeGlyph crossed={visible} />
        </button>
      </div>
      <div className="flex items-center gap-3">
        <div aria-hidden="true" className="flex flex-1 gap-1">
          {Array.from({ length: SEGMENTS }, (_, index) => {
            const filled = index < score;
            // Filling runs left to right; emptying runs right to left.
            const delay = (filled ? index : SEGMENTS - 1 - index) * STAGGER;
            return (
              <span key={index} className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted-foreground/25">
                <motion.span
                  initial={false}
                  animate={{ scaleX: filled ? 1 : 0 }}
                  transition={reduceMotion ? INSTANT : { ...FILL, delay }}
                  className="block h-full origin-left rounded-full bg-primary"
                />
              </span>
            );
          })}
        </div>
        {/* The word carries the meaning, so the meter never depends on colour. */}
        <p role="status" className="min-h-5 w-20 text-right font-medium text-foreground">
          {word && (
            <>
              <span className="sr-only">Password strength: </span>
              {word}
            </>
          )}
        </p>
      </div>
      <ul id={rulesId} className="flex flex-col gap-1.5">
        {rules.map((rule) => {
          const met = rule.test(password);
          return (
            <li key={rule.label} className={cn("flex items-center gap-2", met ? "text-foreground" : "text-muted-foreground")}>
              <RuleMark met={met} transition={reduceMotion ? INSTANT : FILL} />
              <span>
                {rule.label}
                <span className="sr-only">{met ? ", met" : ", not met yet"}</span>
              </span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
